#nullable enable
using System;
using System.Collections.Generic;
using System.IO;

namespace Haiven.Demo.BossRoom
{
    /// <summary>
    /// Public project configuration generated by the Haiven CLI. Field names are
    /// intentionally JSON-shaped so Unity's <c>JsonUtility</c> can deserialize the
    /// asset without an editor-only dependency.
    /// </summary>
    [Serializable]
    public sealed class DemoProjectConfiguration
    {
        public int schemaVersion = 1;
        public string baseUrl = "";
        public string realtimeUrl = "";
        public string appId = "";
        public string integrationId = "";
        public string communityId = "";
        public string channelId = "";
        public string rewardRef = "";
        public string signInUrl = "";
        public string redirectUri = "";

        public string? Read(string name)
        {
            switch (name)
            {
                case DemoSettings.BaseUrlVariable: return baseUrl;
                case DemoSettings.RealtimeUrlVariable: return realtimeUrl;
                case DemoSettings.AppIdVariable: return appId;
                case DemoSettings.IntegrationIdVariable: return integrationId;
                case DemoSettings.CommunityIdVariable: return communityId;
                case DemoSettings.ChannelIdVariable: return channelId;
                case DemoSettings.RewardRefVariable: return rewardRef;
                case DemoSettings.SignInUrlVariable: return signInUrl;
                case DemoSettings.RedirectUriVariable: return redirectUri;
                default: return null;
            }
        }
    }

    /// <summary>
    /// Where the demo connects. Read from the environment so no URL, id or token
    /// is committed into the Boss Room project. The access token is never part
    /// of these settings: it is either the optional HAIVEN_DEMO_ACCESS_TOKEN
    /// shortcut, read at connect time, or the result of signing in with Haiven
    /// (<see cref="DemoSignIn"/>), held only in memory.
    /// </summary>
    public sealed class DemoSettings
    {
        public const string ProjectConfigurationResourcePath = "Haiven/BossRoomDemoSettings";
        public const string BaseUrlVariable = "HAIVEN_DEMO_BASE_URL";
        public const string RealtimeUrlVariable = "HAIVEN_DEMO_REALTIME_URL";
        public const string AppIdVariable = "HAIVEN_DEMO_APP_ID";
        public const string IntegrationIdVariable = "HAIVEN_DEMO_INTEGRATION_ID";
        public const string CommunityIdVariable = "HAIVEN_DEMO_COMMUNITY_ID";
        public const string ChannelIdVariable = "HAIVEN_DEMO_CHANNEL_ID";
        public const string RewardRefVariable = "HAIVEN_DEMO_REWARD_REF";
        public const string AccessTokenVariable = "HAIVEN_DEMO_ACCESS_TOKEN";
        public const string ChatHandleVariable = "HAIVEN_DEMO_CHAT_HANDLE";
        public const string RewardsHandleVariable = "HAIVEN_DEMO_REWARDS_HANDLE";
        public const string ChatHotkeyVariable = "HAIVEN_DEMO_CHAT_HOTKEY";
        public const string ChatStartOpenVariable = "HAIVEN_DEMO_CHAT_START_OPEN";
        public const string RewardsStartOpenVariable = "HAIVEN_DEMO_REWARDS_START_OPEN";
        public const string SignInUrlVariable = "HAIVEN_DEMO_SIGN_IN_URL";
        public const string RedirectUriVariable = "HAIVEN_DEMO_REDIRECT_URI";
        public const string AnalyticsVariable = "HAIVEN_DEMO_ANALYTICS";

        /// <summary>
        /// The loopback redirect registered for the demo integration. Haiven matches
        /// redirects exactly, so the port is fixed; override it only together with
        /// the integration's allowedRedirectUris.
        /// </summary>
        public const string DefaultRedirectUri = "http://127.0.0.1:47615/haiven/callback";

        public DemoSettings(
            string baseUrl,
            string realtimeUrl,
            string appId,
            string integrationId,
            string channelId,
            string rewardRef,
            bool showChatHandle = true,
            bool showRewardsHandle = true,
            bool enableChatHotkey = true,
            bool chatStartsOpen = false,
            bool rewardsStartOpen = false,
            string signInUrl = "",
            string redirectUri = DefaultRedirectUri,
            string communityId = "",
            bool analyticsOptIn = false)
        {
            BaseUrl = baseUrl;
            RealtimeUrl = realtimeUrl;
            AppId = appId;
            IntegrationId = integrationId;
            CommunityId = communityId;
            ChannelId = channelId;
            RewardRef = rewardRef;
            ShowChatHandle = showChatHandle;
            ShowRewardsHandle = showRewardsHandle;
            EnableChatHotkey = enableChatHotkey;
            ChatStartsOpen = chatStartsOpen;
            RewardsStartOpen = rewardsStartOpen;
            SignInUrl = signInUrl.Length > 0 ? signInUrl : DefaultSignInUrl(baseUrl);
            RedirectUri = redirectUri;
            AnalyticsOptIn = analyticsOptIn;
        }

        /// <summary>REST base URL including the version prefix, for example https://api.haiven.gg/v0.</summary>
        public string BaseUrl { get; }

        /// <summary>Realtime socket URL, for example wss://api.haiven.gg/v0/ws.</summary>
        public string RealtimeUrl { get; }

        public string AppId { get; }

        public string IntegrationId { get; }

        /// <summary>The public chat community that owns <see cref="ChannelId"/>.</summary>
        public string CommunityId { get; }

        public string ChannelId { get; }

        /// <summary>The presenter-facing subscriber reward claimed from the rewards drawer.</summary>
        public string RewardRef { get; }

        public bool ShowChatHandle { get; }

        public bool ShowRewardsHandle { get; }

        public bool EnableChatHotkey { get; }

        public bool ChatStartsOpen { get; }

        public bool RewardsStartOpen { get; }

        /// <summary>
        /// Haiven's game sign-in page (<c>/connect/game</c>) the browser opens. Defaults
        /// to the REST base URL's origin, which is where the web app and API share a host.
        /// </summary>
        public string SignInUrl { get; }

        /// <summary>The loopback callback the sign-in page redirects to; see <see cref="DefaultRedirectUri"/>.</summary>
        public string RedirectUri { get; }

        /// <summary>
        /// The presenter opted into SDK analytics and error telemetry. Off unless
        /// <see cref="AnalyticsVariable"/> is set to a true flag value.
        /// </summary>
        public bool AnalyticsOptIn { get; }

        /// <summary>The handoff exchange endpoint under the REST base URL.</summary>
        public string ExchangeUrl => BaseUrl.TrimEnd('/') + "/auth/handoff/exchange";

        /// <summary>The placeholder <see cref="ExpandPlayer"/> replaces in a sign-in URL.</summary>
        public const string PlayerPlaceholder = "__player__";

        /// <summary>
        /// Replaces <see cref="PlayerPlaceholder"/> with this process's player:
        /// the Multiplayer Play Mode name (<c>-name "Player 2"</c> becomes
        /// <c>player-2</c>), else <c>main</c>. Against the local SDK demo stack,
        /// <c>/connect/game?subject=__player__</c> then signs each player in as its
        /// own account, which a lobby on one machine needs.
        /// </summary>
        public static string ExpandPlayer(string url, string[] commandLine)
        {
            if (url.IndexOf(PlayerPlaceholder, StringComparison.Ordinal) < 0) return url;
            var name = "main";
            var at = Array.IndexOf(commandLine, "-name");
            if (at >= 0 && at + 1 < commandLine.Length && commandLine[at + 1].Trim().Length > 0)
                name = commandLine[at + 1].Trim().ToLowerInvariant().Replace(' ', '-');
            return url.Replace(PlayerPlaceholder, Uri.EscapeDataString(name));
        }

        /// <summary><c>{origin}/connect/game</c> for an absolute base URL, otherwise empty.</summary>
        public static string DefaultSignInUrl(string baseUrl) =>
            Uri.TryCreate(baseUrl, UriKind.Absolute, out var parsed)
                ? parsed.GetLeftPart(UriPartial.Authority) + "/connect/game"
                : "";

        /// <summary>The settings, or null with the missing variables named in <paramref name="missing"/>.</summary>
        public static DemoSettings? FromEnvironment(Func<string, string?> read, out string missing)
        {
            var baseUrl = read(BaseUrlVariable) ?? "";
            var realtimeUrl = read(RealtimeUrlVariable) ?? "";
            var appId = read(AppIdVariable) ?? "";
            var integrationId = read(IntegrationIdVariable) ?? "";
            var communityId = read(CommunityIdVariable) ?? "";
            var channelId = read(ChannelIdVariable) ?? "";
            var rewardRef = read(RewardRefVariable) ?? "";
            var absent = new System.Collections.Generic.List<string>();
            if (baseUrl.Length == 0) absent.Add(BaseUrlVariable);
            if (realtimeUrl.Length == 0) absent.Add(RealtimeUrlVariable);
            if (appId.Length == 0) absent.Add(AppIdVariable);
            if (integrationId.Length == 0) absent.Add(IntegrationIdVariable);
            if (channelId.Length == 0) absent.Add(ChannelIdVariable);
            if (rewardRef.Length == 0) absent.Add(RewardRefVariable);
            missing = string.Join(", ", absent);
            return absent.Count == 0
                ? new DemoSettings(
                    baseUrl,
                    realtimeUrl,
                    appId,
                    integrationId,
                    channelId,
                    rewardRef,
                    Flag(read(ChatHandleVariable), true),
                    Flag(read(RewardsHandleVariable), true),
                    Flag(read(ChatHotkeyVariable), true),
                    Flag(read(ChatStartOpenVariable), false),
                    Flag(read(RewardsStartOpenVariable), false),
                    Optional(read(SignInUrlVariable)) ?? "",
                    Optional(read(RedirectUriVariable)) ?? DefaultRedirectUri,
                    communityId,
                    Flag(read(AnalyticsVariable), false))
                : null;
        }

        /// <summary>Reads dotenv assignments as a fallback without executing the file.</summary>
        public static IReadOnlyDictionary<string, string> ReadDotEnv(string path)
        {
            var values = new Dictionary<string, string>(StringComparer.Ordinal);
            if (!File.Exists(path)) return values;
            foreach (var source in File.ReadLines(path))
            {
                var line = source.Trim();
                if (line.Length == 0 || line.StartsWith("#", StringComparison.Ordinal)) continue;
                if (line.StartsWith("export ", StringComparison.Ordinal))
                {
                    line = line.Substring(7).TrimStart();
                }
                var separator = line.IndexOf('=');
                if (separator <= 0) continue;
                var name = line.Substring(0, separator).Trim();
                if (!IsVariableName(name)) continue;
                var value = line.Substring(separator + 1).Trim();
                if (value.Length >= 2 && value[0] == value[value.Length - 1]
                    && (value[0] == '\'' || value[0] == '"'))
                {
                    value = value.Substring(1, value.Length - 2);
                }
                values[name] = value;
            }
            return values;
        }

        /// <summary>Reads the process environment first, then a project dotenv fallback.</summary>
        public static string? ReadSetting(
            string name,
            Func<string, string?> readEnvironment,
            IReadOnlyDictionary<string, string> dotEnv)
        {
            var value = readEnvironment(name);
            return value ?? (dotEnv.TryGetValue(name, out var saved) ? saved : null);
        }

        /// <summary>
        /// Reads explicit process configuration first, then the generated Unity asset,
        /// then the legacy project-root dotenv file.
        /// </summary>
        public static string? ReadSetting(
            string name,
            Func<string, string?> readEnvironment,
            DemoProjectConfiguration? projectConfiguration,
            IReadOnlyDictionary<string, string> dotEnv)
        {
            var value = readEnvironment(name);
            if (value != null) return value;
            var configured = projectConfiguration?.Read(name);
            if (!string.IsNullOrEmpty(configured)) return configured;
            return dotEnv.TryGetValue(name, out var saved) ? saved : null;
        }

        private static bool IsVariableName(string value)
        {
            if (value.Length == 0 || !(char.IsLetter(value[0]) || value[0] == '_')) return false;
            for (var index = 1; index < value.Length; index++)
            {
                if (!(char.IsLetterOrDigit(value[index]) || value[index] == '_')) return false;
            }
            return true;
        }

        private static string? Optional(string? value) =>
            string.IsNullOrWhiteSpace(value) ? null : value!.Trim();

        /// <summary>
        /// Reads an optional environment flag. Unknown values preserve the documented
        /// default so an unrelated host environment cannot unexpectedly hide demo UI.
        /// </summary>
        private static bool Flag(string? value, bool defaultValue)
        {
            if (value == null) return defaultValue;
            switch (value.Trim().ToLowerInvariant())
            {
                case "1":
                case "true":
                case "yes":
                case "on":
                    return true;
                case "0":
                case "false":
                case "no":
                case "off":
                    return false;
                default:
                    return defaultValue;
            }
        }
    }
}
